<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/../lib/ResellerMessaging.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'broadcast');$svc=new ResellerMessaging($pdo,$ctx);$flash='';$ft='ok';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'');try{if($act==='direct'){$r=$svc->enqueueDirect(trim((string)($_POST['user_id']??'')),(string)($_POST['message']??''));$flash='پیام مستقیم در صف قرار گرفت.';}elseif($act==='broadcast'){$r=$svc->enqueueBroadcast((string)($_POST['title']??''),(string)($_POST['message']??''));$flash='پیام برای '.number_format($r['count']).' مخاطب در صف قرار گرفت.';}elseif($act==='cancel'){$flash=$svc->cancel((string)($_POST['broadcast_id']??''))?'ارسال لغو شد.':'ارسال قابل لغو نیست.';}rxp_audit($pdo,$ctx,'messaging.'.$act,$r['broadcast_id']??($_POST['broadcast_id']??''));}catch(Throwable$e){$flash=rxp_public_exception_message($e, basename(__FILE__));$ft='err';}}
$q=$pdo->prepare('SELECT * FROM reseller_broadcasts WHERE actor_reseller_id=? ORDER BY created_at DESC LIMIT 100');try{$q->execute([$ctx['id']]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$rows=[];$flash='Migration 004 اجرا نشده است.';$ft='err';}
rxp_layout_start($ctx,'پیام‌رسانی','messages.php');rxp_flash($flash,$ft);?>
<h1 class="rxp-title">مرکز پیام‌رسانی نماینده</h1><div class="rxp-sub">ارسال مستقیم یا همگانی فقط برای مشتریان متعلق به محدوده شما انجام می‌شود.</div><div class="rxp-card"><h2>پیام مستقیم</h2><form method="post" class="rxp-form"><input type="hidden" name="action" value="direct"><div class="rxp-field"><label>آیدی مشتری متعلق به شما</label><input name="user_id" pattern="\d+" required></div><div class="rxp-field" style="flex:1"><label>متن ساده</label><textarea name="message" maxlength="3500" required style="width:100%;min-width:300px"></textarea></div><button class="rxp-btn">قرار دادن در صف</button></form></div>
<div class="rxp-card"><h2>پیام همگانی</h2><form method="post"><input type="hidden" name="action" value="broadcast"><div class="rxp-field"><label>عنوان داخلی</label><input name="title" maxlength="191"></div><div class="rxp-field"><label>متن ساده؛ بدون Parse Mode</label><textarea name="message" maxlength="3500" required style="width:100%;min-height:110px"></textarea></div><button class="rxp-btn green" onclick="return confirm('پیام برای تمام مشتریان Scope شما صف‌بندی شود؟')">ساخت صف</button></form><p class="rxp-muted">حداکثر ۳ پیام همگانی در روز، حداکثر ۵۰۰۰ مخاطب در هر صف. ارسال توسط Cron و از رباتی انجام می‌شود که مشتری به آن تعلق دارد.</p></div>
<div class="rxp-card"><h2>تاریخچه صف‌ها</h2><div class="rxp-table-wrap"><table class="rxp-table"><tr><th>زمان</th><th>نوع/عنوان</th><th>کل</th><th>ارسال</th><th>خطا</th><th>وضعیت</th><th></th></tr><?php foreach($rows as$r):?><tr><td><?=date('Y/m/d H:i',(int)$r['created_at'])?></td><td><?=rxp_h($r['kind'].' / '.$r['title'])?></td><td><?=$r['total_count']?></td><td><?=$r['sent_count']?></td><td><?=$r['failed_count']?></td><td><span class="rxp-badge"><?=rxp_h($r['status'])?></span></td><td><?php if(in_array($r['status'],['queued','processing'],true)):?><form method="post"><input type="hidden" name="action" value="cancel"><input type="hidden" name="broadcast_id" value="<?=rxp_h($r['broadcast_id'])?>"><button class="rxp-btn red">لغو</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php rxp_layout_end();
